PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?timeHorizon 
       (SUM(xsd:decimal(?cfAmount)) AS ?totalCashFlow) 
       (AVG(xsd:decimal(?scenarioChange)) AS ?avgScenarioChange) 
       (AVG(xsd:decimal(?allocPct)) AS ?avgSectorAllocationPct) 
       (SUM(xsd:decimal(?holdingValue)) AS ?totalHoldingValue)
WHERE {
  {
    SELECT ?investorId ?timeHorizon (SUM(xsd:decimal(?amount)) AS ?cfAmount)
    WHERE {
      ?cf a wm:CashFlow ;
          wm:investorId ?investorId ;
          wm:date ?date ;
          wm:amount ?amount .
      BIND(STR(?date) AS ?dateStr)
      BIND(SUBSTR(?dateStr,1,4) AS ?timeHorizon)   # assume year is first 4 chars
    }
    GROUP BY ?investorId ?timeHorizon
  }
  {
    SELECT ?investorId ?timeHorizon ((?newAllocationPct - ?currentAllocationPct) AS ?scenarioChange)
    WHERE {
      ?sr a wm:ScenarioRebalancing ;
          wm:investorId ?investorId ;
          wm:currentAllocationPct ?currentAllocationPct ;
          wm:newAllocationPct ?newAllocationPct .
      BIND("overall" AS ?timeHorizon)
    }
    GROUP BY ?investorId ?timeHorizon ?newAllocationPct ?currentAllocationPct
  }
  {
    SELECT ?investorId ?timeHorizon (AVG(xsd:decimal(?allocationPct)) AS ?allocPct)
    WHERE {
      ?sa a wm:SectorAllocation ;
          wm:investorId ?investorId ;
          wm:allocationPct ?allocationPct .
      BIND("overall" AS ?timeHorizon)
    }
    GROUP BY ?investorId ?timeHorizon
  }
  {
    SELECT ?investorId ?timeHorizon (SUM(xsd:decimal(?currentValue)) AS ?holdingValue)
    WHERE {
      ?ph a wm:PortfolioHolding ;
          wm:investorId ?investorId ;
          wm:currentValue ?currentValue .
      BIND("overall" AS ?timeHorizon)
    }
    GROUP BY ?investorId ?timeHorizon
  }
}
GROUP BY ?timeHorizon

